import React from 'react';
import { motion, useReducedMotion } from 'framer-motion';

const DEFINITION =
  'Certainty of lift represents the likelihood that the measured lift is generated by your campaigns, and not due to chance. The certainty of lift can sometimes be referred to as the \u201Cstatistical significance of lift results.\u201D';

const LINK_LABEL = 'Learn more about certainty of lift detection';

const ITERATIONS = [
  {
    id: 'low',
    label: '50% or less',
    intent: 'Be careful',
    summary:
      'Since your results have a 50% or less significance, you should be careful with how you use these results.',
  },
  {
    id: 'directional',
    label: '80% certainty',
    intent: 'Directional',
    summary:
      'Since your results have a 80% significance, you can use these results as directional insights.',
  },
  {
    id: 'confident',
    label: '70% certainty',
    intent: 'Be confident',
    summary:
      'Since your results have a 70% significance, you can be confident your campaign generated lift.',
  },
] as const;

export function FlexibleLiftCertaintyIterations() {
  const reduceMotion = useReducedMotion();

  return (
    <section
      aria-labelledby="flexible-lift-iterations-heading"
      className="my-5 border border-color-border-default bg-color-bg-subtle px-5 py-6 first:mt-0 last:mb-0 sm:px-6 sm:py-8 md:p-8"
    >
      <h3
        id="flexible-lift-iterations-heading"
        className="font-heading text-[22.5px] font-semibold leading-[1.2] tracking-[-0.01em] text-color-text-primary"
      >
        Exploring what each percentage should mean
      </h3>
      <p className="mt-3 font-body text-[16px] leading-normal text-color-text-primary sm:text-[18px]">
        Each card is a different iteration of the same tooltip. I was trying to
        be explicit about what that percentage meant for the advertiser&apos;s
        next decision&mdash;whether to treat the result as something to be
        careful with, a directional insight, or evidence the campaign actually
        drove lift.
      </p>

      <div
        className="mt-6 grid grid-cols-1 gap-6 md:mt-8 md:grid-cols-3 md:gap-5"
        aria-label="Tooltip copy iterations for different certainty levels"
      >
        {ITERATIONS.map((card, index) => (
          <div key={card.id} className="flex h-full flex-col">
            <p className="mb-2 font-body text-sm font-semibold text-color-text-primary">
              {card.label}
              <span className="font-normal">
                {' '}
                &middot; {card.intent}
              </span>
            </p>
            <motion.article
              initial={reduceMotion ? false : { opacity: 0, y: 16 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true, amount: 0.4 }}
              transition={{
                duration: 0.6,
                delay: reduceMotion ? 0 : index * 0.08,
                ease: [0.16, 1, 0.3, 1],
              }}
              className="flex h-full flex-col rounded-2xl bg-color-bg-surface px-4 py-4 font-[Roboto,Helvetica,Arial,sans-serif] text-[14px] leading-[1.5] text-[#3c4043] shadow-[0_2px_6px_rgba(41,64,80,0.18)] ring-1 ring-black/5 sm:px-5 sm:py-5"
            >
              <p>{DEFINITION}</p>
              <p className="mt-5">{card.summary}</p>
              <span className="mt-auto inline-block pt-5 text-[#1a73e8]">
                {LINK_LABEL}
              </span>
            </motion.article>
          </div>
        ))}
      </div>
    </section>
  );
}
